#if UNITY_EDITOR
using System;
using System.Collections;
using System.Linq;
using System.Reflection;
using NUnit.Framework;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;

// Deliberately supplied final values validate presentation; never physical scores.
public sealed class CornholeResultsLifecycleTests
{
    const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
    static Type Runtime(string name)=>Type.GetType("LWS.TruckSports."+name+", Assembly-CSharp",true);
    static object Get(object owner,string name)=>owner.GetType().GetField(name,Any) is FieldInfo field?field.GetValue(owner):owner.GetType().GetProperty(name,Any).GetValue(owner);
    static void Set(object owner,string name,object value){if(owner.GetType().GetField(name,Any) is FieldInfo field)field.SetValue(owner,value);else owner.GetType().GetProperty(name,Any).SetValue(owner,value);}
    static object Call(object owner,string name,params object[] args)=>owner.GetType().GetMethods(Any).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length&&m.GetParameters().Select((p,i)=>args[i]==null||p.ParameterType.IsInstanceOfType(args[i])).All(value=>value)).Invoke(owner,args);
    static Rect Pixels(RectTransform rect,Camera ui){var p=new Vector3[4];rect.GetWorldCorners(p);var a=RectTransformUtility.WorldToScreenPoint(ui,p[0]);var b=RectTransformUtility.WorldToScreenPoint(ui,p[2]);return Rect.MinMaxRect(a.x,a.y,b.x,b.y);}
    [UnityTest,Timeout(240000)]public IEnumerator SyntheticOriginalFinalValuesKeepTiesIdentitiesLayoutAndFinalReviewCaption()
    {
        var prefs=(IDisposable)Runtime("SportsPrefs").GetMethod("IsolateValidation").Invoke(null,new object[]{"ExplicitCornholeResultUI"});Runtime("SportsParticipantRegistry").GetMethod("ForgetCache").Invoke(null,null);var isolation=new GameObject("Explicit supplied Cornhole result UI, not physical finishes");UnityEngine.Object.DontDestroyOnLoad(isolation);isolation.AddComponent(Runtime("SportsProbeInputIsolation"));Component match=null;
        try
        {
            EditorSceneManager.LoadSceneInPlayMode("Assets/TruckCornhole/Scenes/TruckCornhole.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;match=(Component)UnityEngine.Object.FindAnyObjectByType(Type.GetType("LWS.TruckCornhole.CornholeMatch, Assembly-CSharp",true));var menus=(Component)Get(match,"menus");var board=menus.GetComponentsInChildren(Runtime("SportsResultsPresentation"),true).Cast<Component>().Single();var source=Get(board,"source");Assert.That(Get(source,"cornhole"),Is.SameAs(match));var pages=(GameObject[])Get(menus,"pages");var resultPage=pages[6];var controls=resultPage.GetComponentsInChildren(Runtime("SportsMenuAction"),true).Cast<Component>().Select(a=>(RectTransform)a.transform).ToArray();Assert.That(controls.Length,Is.GreaterThanOrEqualTo(4));var viewRows=(Array)Get(board,"rows");int caseIndex=0;
            foreach(var supplied in new[]{new[]{0},new[]{6,6},new[]{3,7,7},new[]{3,6,7,6},new[]{0,0,0,0}})
            {
                ((Behaviour)match).enabled=true;Call(match,"ChangeSetup");Set(Get(match,"setup"),"count",supplied.Length);Call(match,"AllAI");Runtime("SportsCameraOptions").GetMethod("Set").Invoke(null,new object[]{true});var players=(Array)Get(Get(match,"setup"),"players");for(int i=0;i<supplied.Length;i++){var p=players.GetValue(i);Runtime("SportsParticipantRegistry").GetMethod("Rename").Invoke(null,new[]{Get(p,"participantId"),(object)"Alexandra Montgomery <same crew>",Get(p,"color"),true});}Call(match,"RefreshParticipants",false);Assert.That(Call(match,"StartMatch"),Is.True);((Behaviour)match).enabled=false;Time.timeScale=0;var totals=(int[])Get(match,"totals");Array.Clear(totals,0,totals.Length);Array.Copy(supplied,totals,supplied.Length);var last=(int[])Get(match,"lastRound");for(int i=0;i<4;i++)last[i]=i;var winners=(int[])Type.GetType("LWS.TruckCornhole.CornholeRules, Assembly-CSharp",true).GetMethod("Winners").Invoke(null,new object[]{totals,supplied.Length});Set(match,"winners",winners);Set(match,"Round",5);Set(match,"RoundFinalizations",5);Set(match,"Finished",true);Set(match,"RoundBreak",false);int[] original=(int[])totals.Clone();Call(menus,"Show",Enum.Parse(Type.GetType("LWS.TruckCornhole.CornholeScreen, Assembly-CSharp",true),"Result"));yield return null;yield return null;Call(board,"CompleteAnimations");yield return null;Assert.That(Get(board,"Displaying"),Is.True);Assert.That(Get(Get(source,"OriginalResult"),"enabled"),Is.False);var snapshot=Get(board,"Snapshot");var rows=((IEnumerable)Get(snapshot,"Rows")).Cast<object>().ToArray();Assert.That(rows.Length,Is.EqualTo(supplied.Length));Assert.That(rows.Select(row=>(string)Get(row,"ParticipantId")).Distinct().Count(),Is.EqualTo(supplied.Length));
                foreach(var row in rows){int slot=(int)Get(row,"Slot");Assert.That(Get(row,"Measurement"),Is.EqualTo((double)supplied[slot]));Assert.That(Get(row,"Winner"),Is.EqualTo(winners.Contains(slot)));int rank=1+supplied.Count(value=>value>supplied[slot]);Assert.That(Get(row,"Place"),Is.EqualTo(rank));Assert.That(Get(row,"DisplayName"),Is.EqualTo("Alexandra Montgomery <same crew>"));Assert.That(Get(row,"Detail"),Is.EqualTo("FINAL ROUND +"+slot+" · 5 BANKS"));}
                var cameras=((Array)Get(match,"courses")).Cast<object>().Select(course=>(Camera)Get(Get(course,"chase"),"view")).ToArray();var save=Runtime("SportsControlledCapture").GetMethods().Single(m=>m.Name=="Save"&&m.GetParameters().Length==6);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)}){Action<Camera> inspect=ui=>{Canvas.ForceUpdateCanvases();for(int i=0;i<rows.Length;i++){var view=viewRows.GetValue(i);var rect=Pixels((RectTransform)Get(view,"rect"),ui);Assert.That(rect.xMin,Is.GreaterThanOrEqualTo(-2));Assert.That(rect.yMin,Is.GreaterThanOrEqualTo(-2));Assert.That(rect.xMax,Is.LessThanOrEqualTo(size.x+2));Assert.That(rect.yMax,Is.LessThanOrEqualTo(size.y+2));foreach(var control in controls)Assert.That(rect.Overlaps(Pixels(control,ui)),Is.False,"Actual ranked cards preserve all four original controls.");foreach(string name in new[]{"value","detail","place"}){var text=Get(view,name);Call(text,"ForceMeshUpdate",false,false);Assert.That(Get(text,"isTextOverflowing"),Is.False);}Assert.That(Get(Get(view,"value"),"text"),Is.EqualTo(Get(rows[i],"Value")));StringAssert.DoesNotContain("<same crew>",(string)Get(Get(view,"name"),"text"));}};save.Invoke(null,new object[]{menus.GetComponent<Canvas>(),cameras,size.x,size.y,"Logs/TruckSports/PlaytestRepair/CornholeRankedResults/synthetic-case-"+caseIndex+"-"+size.y+".png",inspect});}
                Assert.That(totals,Is.EqualTo(original));Assert.That(Get(Get(match,"ScoreJournal"),"Count"),Is.Zero,"Rendering supplied final values cannot create points or receipts.");Call(menus,"Show",Enum.Parse(Type.GetType("LWS.TruckCornhole.CornholeScreen, Assembly-CSharp",true),"Play"));yield return new WaitForSecondsRealtime(.15f);var headers=(Array)Get(menus,"headers");for(int i=0;i<supplied.Length;i++){string text=(string)Get(headers.GetValue(i),"text");StringAssert.Contains("ROUND FINAL +"+last[i],text);StringAssert.DoesNotContain("PROVISIONAL",text);}Assert.That(totals,Is.EqualTo(original));string old=(string)Get(match,"MatchId");((Behaviour)match).enabled=true;Call(match,"ChangeSetup");Assert.That(Call(match,"StartMatch"),Is.True);yield return null;Assert.That(Get(match,"MatchId"),Is.Not.EqualTo(old));Assert.That(Get(board,"Snapshot"),Is.Null);Assert.That(Get(Get(source,"OriginalResult"),"enabled"),Is.True);caseIndex++;
            }
            TestContext.WriteLine("SYNTHETIC_CORNHOLE_RESULTS five supplied models,1–4rosters, shared tied/zero wins, full stable identities, escaped names, actual totals/final-bank stats,10controlled native renders, unchanged points/journal, final-review caption and fresh rematch. Not actual physical scoring or human playtest.");
        }
        finally{Time.timeScale=1;if(match!=null){((Behaviour)match).enabled=true;Call(match,"ChangeSetup");}UnityEngine.Object.DestroyImmediate(isolation);prefs.Dispose();Runtime("SportsParticipantRegistry").GetMethod("ForgetCache").Invoke(null,null);}
    }
}
#endif
